namespace ghidra.util.table.field;

using ghidra.docking.settings;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.program.util;

/**
 * This table column displays the Label for either the program location or the address
 * associated with a row in the table.
 */
public class LabelTableColumn : ProgramLocationTableColumnExtensionPoint<ProgramLocation, string> {

	/* @Override */
	public ProgramLocation getProgramLocation(ProgramLocation rowObject, Settings settings,
			Program program, ServiceProvider serviceProvider) {

		Symbol symbol = getSymbol(rowObject, program);

		if (symbol != null) {
			return symbol.getProgramLocation();
		}
		return rowObject;
	}

	/* @Override */
	public string getColumnName() {
		return "Label";
	}

	/* @Override */
	public string getValue(ProgramLocation rowObject, Settings settings, Program program,
			ServiceProvider serviceProvider)
    {
		if (rowObject == null) {
			return null; // This can happen when using mapped table columns
		}

		if (rowObject is LabelFieldLocation) {
			LabelFieldLocation labelFieldLocation = (LabelFieldLocation) rowObject;
			return labelFieldLocation.getSymbolPath().getName();
		}
		Symbol symbol = getSymbol(rowObject, program);
		if (symbol != null) {
			return symbol.getName();
		}

		Address address = rowObject.getAddress();
		if (address == Address.EXT_FROM_ADDRESS) {
			return address.toString();
		}

		return null;
	}

	private Symbol getSymbol(ProgramLocation rowObject, Program program)
    {
		if (rowObject == null) {
			// this can happen when a bookmark is deleted and we use a mapping column that can no
			// longer find the bookmark for the BookmarkRowObject
			return null;
		}

		ProgramLocation location = rowObject;
		if (rowObject is VariableLocation) {
			Variable var = ((VariableLocation) rowObject).getVariable();
			if (var != null) {
				return var.getSymbol();
			}
		}
		Address address = location.getAddress();
		SymbolTable symbolTable = program.getSymbolTable();

		return symbolTable.getPrimarySymbol(address);
	}

	/* @Override */
	public int getColumnPreferredWidth() {
		// make this big enough for normal labels values to display
		return 200;
	}
}
